questionvariables.text:
/* Fixed: one specific proof. Options in a fixed order, the best summary second. */
ta1: [
 [sumA, false, "Check that \\(m^2 - 1\\) is a multiple of 3 for \\(m = 1, 2, 4, 5\\) and \\(7\\), and conclude that the same holds for every integer that is not a multiple of 3."],
 [sumB, true, "Write each integer that is not a multiple of 3 as \\(3k + 1\\) or \\(3k + 2\\), and in each case factorise \\(m^2 - 1\\) as a difference of two squares to show that it has a factor of 3."],
 [sumC, false, "Factorise \\(m^2 - 1\\) as \\((m - 1)(m + 1)\\), and note that a product of two integers like this must be a multiple of 3."],
 [sumD, false, "Split all the integers into multiples of 3 and integers that are not multiples of 3, and show that \\(m^2 - 1\\) is a multiple of 3 in each of these two cases."]
];
